[Form]
public class METSalesOrderShipments extends FormRun
{
    METOrderTransactionType     orderTransactionType;


}

/// <summary>
/// Update design based on transaction type
/// </summary>
private void updateDesign()
{
    if (orderTransactionType == METOrderTransactionType::TransferOrder)
    {
        TransferOrderShipment.visible(true);
        SalesOrderShipment.visible(false);
        METSalesOrderShipmentLoadHeader_Warehouse1.label("@MET:FromWH");
        METSalesOrderShipmentLoadHeader_CustAccount.visible(false);
        METSalesOrderShipmentLoadHeader_Warehouse2.label("@MET:FromWH");
        ShipmentLineGrid_OrderNum.label("@MET:TransferOrder");
    }
    else
    {
        SalesOrderShipment.visible(true);
        TransferOrderShipment.visible(false);
        METSalesOrderShipmentLoadHeader_ToWarehouse.visible(false);
        METSalesOrderShipmentLoadHeader_ToWarehouse1.visible(false);
        ShipmentLineGrid_OrderNum.label("@MET:SalesOrder");
    }
}

/// <summary>
/// Datasource initialize method
/// </summary>
public void init()
{
    super();

    orderTransactionType = element.args().parmEnum();
    element.updateDesign();

    METSalesOrderShipmentLoadHeader_ds.queryBuildDataSource().addRange(fieldNum(METSalesOrderShipmentLoadHeader, TransactionType)).value(queryValue(orderTransactionType));
    METSalesOrderShipmentLoadHeader_ds.queryBuildDataSource().addSortField(fieldNum(METSalesOrderShipmentLoadHeader,ShipmentId),SortOrder::Ascending);

    if (element.args().dataset() == tableNum(InventTransferLine))
    {
        InventTransferLine  inventTransferLine = element.args().record();

        QueryBuildDataSource  qbds = this.queryBuildDataSource();
        QueryBuildDataSource    qbds1 = qbds.addDataSource(tableNum(METSalesOrderShipmentLoadLines));

        qbds1.joinMode(JoinMode::InnerJoin);
        qbds1.addLink(fieldNum(METSalesOrderShipmentLoadHeader, ShipmentId), fieldNum(METSalesOrderShipmentLoadLines, ShipmentId));

        qbds1.addRange(fieldNum(METSalesOrderShipmentLoadLines, OrderNum)).value(queryValue(inventTransferLine.TransferId));
        qbds1.addRange(fieldNum(METSalesOrderShipmentLoadLines, OrderNum)).value(queryValue(inventTransferLine.LineNum));
    }
    else if (element.args().dataset() == tableNum(SalesLine))
    {
        SalesLine   salesLine = element.args().record();

        QueryBuildDataSource  qbds = this.queryBuildDataSource();
        QueryBuildDataSource    qbds1 = qbds.addDataSource(tableNum(METSalesOrderShipmentLoadLines));

        qbds1.joinMode(JoinMode::InnerJoin);
        qbds1.addLink(fieldNum(METSalesOrderShipmentLoadHeader, ShipmentId), fieldNum(METSalesOrderShipmentLoadLines, ShipmentId));
        qbds1.addRange(fieldNum(METSalesOrderShipmentLoadLines, OrderNum)).value(queryValue(salesLine.SalesId));
        qbds1.addRange(fieldNum(METSalesOrderShipmentLoadLines, OrderNum)).value(queryValue(salesLine.LineNum));

    }
}

/// <summary>
/// Datasource active method
/// </summary>
/// <returns>Integer</returns>
public int active()
{
    int ret;

    ret = super();

    METSalesOrderShipmentLoadHeader_ds.allowDelete(METSalesOrderShipmentLoadHeader.ShipmentStatus == MetShipmentStatus::Open);
    return ret;
}

/// <summary>
/// Jump ref method to trigger Sales order or transfer order based on transaction type
/// </summary>
public void jumpRef()
{
    Args            args = new Args();
    MenuFunction    menuFunction;

    if (orderTransactionType ==METOrderTransactionType::SalesOrder)
    {
        SalesTable      salesTable = SalesTable::find(METSalesOrderShipmentLoadLines.OrderNum);
        args.record(salesTable);
        args.lookupRecord(salesTable);

        menuFunction = new MenuFunction(menuitemDisplayStr(SalesTable), MenuItemType::Display);
        menuFunction.run(args);
    }
    else if (orderTransactionType == METOrderTransactionType::TransferOrder)
    {
        InventTransferTable      inventTransferTable = InventTransferTable::find(METSalesOrderShipmentLoadLines.OrderNum);
        args.record(inventTransferTable);
        args.lookupRecord(inventTransferTable);

        menuFunction = new MenuFunction(menuitemDisplayStr(InventTransferOrder), MenuItemType::Display);
        menuFunction.run(args);
    }
    else
    {
        super();
    }
}
